KG42.register("rules-b68588b805584e4c12883584",{"id":"11-p2p_mechanisms_evaluation::v141-c-R011","paper":"11-p2p_mechanisms_evaluation","record":{"rule_id":"v141-c-R011","mechanism_id":"v141-a-M02","name":"Demand submission","process_stage":"bidding","market_meaning":"Each energy bid must report demand separately from generation at every time step, rather than reporting only overall net demand. Scope: Demand information in each participant's MMR energy bid.","independence_rationale":"Relations governed by the approved function bidding.demand under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["bidding.demand"],"E":[],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"Demand information in each participant's MMR energy bid.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g07-ev-06"]},"x":[{"variable_id":"v141-c-R011-x-dem-bid-t","symbol":"e_{dem,t}^{bid}","meaning":"Demand component of the MMR energy bid submitted by a prosumer at time step t; source formula (A24) defines it as the sum of optimal flexible-appliance power plus EV charging power divided by charging efficiency plus inflexible must-run demand.","kind":"operational","domain":"Time-indexed demand component of an MMR energy bid, for t in the scheduling horizon T.","unit":null,"indices":["t"],"evidence_ids":["v141-b-g07-ev-06"]},{"variable_id":"v141-c-R011-x-delta-t-star","symbol":"x_{\\delta,t}^*","meaning":"Optimal power of flexible appliance δ at time step t from the prosumer decision-making model, used as the first term in the MMR demand-bid component.","kind":"operational","domain":"Power of flexible appliance δ at time step t, for δ in the flexible-appliance set A_f and t in T, as prescribed by the decision-making model.","unit":null,"indices":["δ","t"],"evidence_ids":["v141-b-g07-ev-06"]},{"variable_id":"v141-c-R011-x-ch-t-star","symbol":"x_t^{ch*}","meaning":"Optimal EV charging power at time step t from the prosumer decision-making model, divided by charging efficiency in the MMR demand-bid component.","kind":"operational","domain":"EV charging power at time step t, for t in T, as prescribed by the decision-making model.","unit":null,"indices":["t"],"evidence_ids":["v141-b-g07-ev-06"]}],"theta":[{"parameter_id":"v141-c-R011-theta-eta-ch","symbol":"\\eta^{ch}","meaning":"Charging efficiency of the electric vehicle; source formula (A24) divides EV charging power by this efficiency in the demand-bid component.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g07-ev-06"]},{"parameter_id":"v141-c-R011-theta-P-must-run-t","symbol":"P_t^{must-run}","meaning":"Inflexible must-run demand at time step t included in the MMR demand-bid component.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["t"],"evidence_ids":["v141-b-g07-ev-06"]}],"phi":[{"constraint_id":"v141-c-R011-C001","kind":"procedural","role":"core","statement":"Each energy bid must report demand separately from generation at every time step, rather than reporting only overall net demand. Scope: Demand information in each participant's MMR energy bid.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g07-ev-06"]},{"constraint_id":"v141-c-R011-C002","kind":"mathematical","role":"core","statement":"The demand component of the MMR energy bid at time step t is defined by e_{dem,t}^{bid} = (sum over flexible appliances δ in A_f of x_{δ,t}^*) + (x_t^{ch*}/η^{ch} + P_t^{must-run}), for t in T; this demand component is reported separately from the generation component.","expression":"e_{dem}^{bid} = \\{ e_{dem,t}^{bid} \\mid e_{dem,t}^{bid} = \\left( \\sum_{\\delta \\in \\mathcal{A}_f} x_{\\delta,t}^* \\right) + \\left( \\frac{x_t^{ch*}}{\\eta^{ch}} + P_t^{must-run} \\right), t \\in T \\}","formalization_origin":"source","template_id":null,"members":["bidding.demand"],"variable_refs":["v141-c-R011-x-dem-bid-t","v141-c-R011-x-delta-t-star","v141-c-R011-x-ch-t-star"],"parameter_refs":["v141-c-R011-theta-eta-ch","v141-c-R011-theta-P-must-run-t"],"evidence_ids":["v141-b-g07-ev-06"]}],"pi":[{"evidence_id":"v141-b-g07-ev-06","location":{"location_id":"src-d485825b0d-p26-c2r4__v141-a-M02-bidding","page":26,"printed_page":"1018","section":"A.2.2","anchor_text":"(A24) the internal price in diﬀerent ways according to the relationship between total n is equal to ","equation_id":"A24","figure_id":null,"table_id":null,"image_ref":"pages/page-26.png","occurrence_role":"formula"},"source_text":"The MMR mechanism requires each prosumer to provide the energy bid that contains both generation and demand at each time step separately rather than an overall net demand as that in the SDR mechanism:\n\ne^{bid} = e_{gen}^{bid} \\cup e_{dem}^{bid}\n= \\{ e_{gen,t}^{bid} \\mid e_{gen,t}^{bid} = (x_t^{dis*} \\eta^{dis}) - P_{PV,t}, t \\in T \\}\n\\cup \\{ e_{dem,t}^{bid} \\mid e_{dem,t}^{bid} = \\left( \\sum_{\\delta \\in \\mathcal{A}_f} x_{\\delta,t}^* \\right) + \\left( \\frac{x_t^{ch*}}{\\eta^{ch}} + P_t^{must-run} \\right), t \\in T \\}  (A24)"}],"field_notes":{"empty_E_reason":"C explicitly supplied only source-backed unary facts for this function; other graph gaps remain reviewable.","empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M02-bidding"],"extras":{"decision_anchor":"bidding.demand","graph_fact_supports":[[{"evidence_id":"v141-b-g07-ev-06","quote":"The MMR mechanism requires each prosumer to provide the energy bid that contains both generation and demand at each time step separately rather than an overall net demand as that in the SDR mechanism:"}]],"C2_formalization":{"graph_sha256":"540ee266396b18cb6b659b3ec13e5abda2edc5f0cb8c1f67eabdd02fbd5731fd","applicability":"formalized","reason":"The existing C001 states the procedural demand-reporting requirement. The same M02 evidence, v141-b-g07-ev-06, supplies formula (A24), whose demand line defines the separate demand component of an MMR energy bid: e_{dem,t}^{bid} = (sum over flexible appliances δ in A_f of x_{δ,t}^*) + (x_t^{ch*}/η^{ch} + P_t^{must-run}) for t in T. The frozen graph contains the target node bidding.demand and no edges; this algebraic definition can be attached to that node without inventing graph structure. The C1 empty x/theta reflected a graph-draft limitation, not a source claim that no variables or parameters exist, so source-supported variables and parameters from the same formula are declared and bound to bidding.demand. B evidence remains unreviewed in this experiment; this formalization is therefore provisional and does not assert independent source verification.","bindings":[{"object_id":"v141-c-R011-C002","node_ids":["bidding.demand"],"edge_ids":[],"rationale":"Formula (A24)'s demand component defines the demand information that must be reported in an MMR energy bid, exactly the relation governed by the frozen node bidding.demand. No edge exists or is needed for this algebraic definition."},{"object_id":"v141-c-R011-x-dem-bid-t","node_ids":["bidding.demand"],"edge_ids":[],"rationale":"The symbol e_{dem,t}^{bid} is the demand component of the MMR energy bid, so it directly instantiates the bidding.demand relation in the frozen graph."},{"object_id":"v141-c-R011-x-delta-t-star","node_ids":["bidding.demand"],"edge_ids":[],"rationale":"x_{\\delta,t}^* is an optimal flexible-appliance schedule quantity that feeds the demand component of the MMR energy bid; the frozen graph registers only bidding.demand for this rule, so it is bound there."},{"object_id":"v141-c-R011-x-ch-t-star","node_ids":["bidding.demand"],"edge_ids":[],"rationale":"x_t^{ch*} is the optimal EV charging quantity that enters the demand component of the MMR energy bid; the frozen graph registers only bidding.demand for this rule, so it is bound there."},{"object_id":"v141-c-R011-theta-eta-ch","node_ids":["bidding.demand"],"edge_ids":[],"rationale":"Charging efficiency η^{ch} scales EV charging power inside the demand-bid component governed by bidding.demand."},{"object_id":"v141-c-R011-theta-P-must-run-t","node_ids":["bidding.demand"],"edge_ids":[],"rationale":"P_t^{must-run} is an inflexible demand term included in the demand-bid component governed by bidding.demand."}],"revision_requests":["B evidence v141-b-g07-ev-06 remains unverified in this experiment; perform the normal B source audit to confirm formula (A24), the definitions of x_{\\delta,t}^*, x_t^{ch*}, \\eta^{ch}, P_t^{must-run}, T and \\mathcal{A}_f, and their units before scientific acceptance.","No C1 graph revision is requested: the demand-bid formula can be represented by the existing node bidding.demand with no edge."]}},"quarantined_references":[]}});
